import json
import math
import re
from pathlib import Path
from typing import Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

IDENTIFIER = r"^[a-z][a-z0-9_]*$"


class StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid")


class StateField(StrictModel):
    type: Literal["string", "number", "boolean", "object", "array"]
    nullable: bool = False
    properties: dict[str, "StateField"] = Field(default_factory=dict)
    items: "StateField | None" = None
    enum: list[str] = Field(default_factory=list)

    @model_validator(mode="after")
    def structure(self):
        if (self.type == "array") != (self.items is not None):
            raise ValueError("Only arrays require items")
        if self.properties and self.type != "object":
            raise ValueError("Only objects have properties")
        if self.enum and self.type != "string":
            raise ValueError("Only strings have enum values")
        return self

    def check(self, value, path="state") -> None:
        if value is None and self.nullable:
            return
        valid = {"string": isinstance(value, str), "number": type(value) in (int, float) and math.isfinite(value),
                 "boolean": type(value) is bool, "object": isinstance(value, dict), "array": isinstance(value, list)}
        if not valid[self.type]:
            raise ValueError(f"{path}: expected {self.type}{' or null' if self.nullable else ''}")
        if self.enum and value not in self.enum:
            raise ValueError(f"{path}: expected one of {self.enum}")
        if self.type == "object":
            if set(value) != set(self.properties):
                raise ValueError(f"{path}: fields differ (missing {set(self.properties) - set(value)}, extra {set(value) - set(self.properties)})")
            for key, field in self.properties.items():
                field.check(value[key], f"{path}.{key}")
        elif self.type == "array":
            assert self.items is not None
            for i, item in enumerate(value):
                self.items.check(item, f"{path}[{i}]")

    def typescript(self) -> str:
        if self.type == "object":
            text = "{ " + "; ".join(f"{json.dumps(k)}: {v.typescript()}" for k, v in self.properties.items()) + " }"
        elif self.type == "array":
            assert self.items is not None
            text = f"Array<{self.items.typescript()}>"
        elif self.enum:
            text = " | ".join(json.dumps(v) for v in self.enum)
        else:
            text = self.type
        return f"({text}) | null" if self.nullable else text


def scalar(kind, **kwargs):
    return StateField(type=kind, **kwargs)


def obj(**properties):
    return StateField(type="object", properties=properties)


BASE_STATE = {
    "world": obj(name=scalar("string"), seed=scalar("string"), difficulty=scalar("string")),
    "week": scalar("number"), "weeks": scalar("number"),
    "story": StateField(type="object", nullable=True, properties={"tag": scalar("string"), "text": scalar("string"), "tone": scalar("string", enum=["amber", "mint", "coral"])}),
    "discoveries": obj(total=scalar("number"), found=scalar("array", items=scalar("string")), hidden=scalar("array", items=scalar("string", nullable=True))),
    "agent": obj(experiment=scalar("number"), experiments=scalar("number"), mode=scalar("string", enum=["you", "agent"]), scores=scalar("array", items=scalar("number")), baseline=scalar("number"), now=scalar("string"), code=scalar("string")),
    "active": scalar("string", nullable=True), "done": scalar("boolean"),
}


