                raise ValueError("Site tile lies outside grid")
        if any(not re.fullmatch(r"#[0-9a-fA-F]{6}", color) for color in self.visual.palette.values()):
            raise ValueError("Palette values must be hex colours")
        return self

    def markdown(self) -> str:
